      +'<span class="s-card-line"><i></i>'+esc(subName(p))+'</span><h3><a href="'+u+'">'+esc(p.name)+'</a></h3><p class="s-desc">'+esc(p.desc)+'</p>'
      +'<span class="s-dim">Sort: '+esc(tileSc(p).join(' / '))+'</span>'
      +'<div class="s-price"><small>alates</small>'+eur.format(tileFrom(p))+'<em class="s-mq">/m²</em><span>Ilma km-ta · transport eraldi</span></div>'
      +'<div class="s-card-foot"><a class="s-add" href="'+u+'" aria-label="Valige ruutmeetrid: '+esc(p.name)+'">'+IC.plus+'<span>Valige m²</span></a>'
      +'<button class="s-fav" type="button" data-fav="'+esc(p.id)+'" aria-pressed="'+fav+'" aria-label="Salvesta lemmikutesse">'+IC.heart+'</button></div>'
      +'</article>';
