    h+='<dl class="s-specs"><dt>Formaat</dt><dd>'+esc(t.fmt.map(function(x){return x.replace('x','×')}).join(' · '))+' cm</dd><dt>Paksus</dt><dd>'+esc(t.sp)+'</dd><dt>Viimistlus</dt><dd>'+esc(t.fin.join(' / ')||'Naturale')+'</dd><dt>Serv</dt><dd>'+(t.rett?'Rektifitseeritud':'Rektifitseerimata')+'</dd><dt>Materjal</dt><dd>'+esc(t.mat)+'</dd>'+(t.extra.length?'<dt>Märkused</dt><dd>'+esc(t.extra.join(', '))+'</dd>':'')+'</dl>';
