    var h='<span class="s-card-line"><i></i>'+esc(subName(p))+'</span><h2 id="s-pm-t">'+esc(p.name)+'</h2><p class="s-pm-desc">'+esc(p.desc)+'. Valmistatud portselankivi plaatidest, servad ühendatud 45° nurga all.</p>';
    if(q)h+='<fieldset class="s-opt"><legend>Pikkus <small>'+K.big.min+'–'+K.big.max+' cm, kuni</small></legend><div class="s-chips" id="o-bw">'+[150,180,250].map(function(w){return '<button type="button" class="s-chip" data-v="'+w+'">'+w+' cm</button>'}).join('')+'</div><div class="s-dims one"><label>Pikkus (cm)<input type="number" inputmode="numeric" id="o-w" min="'+K.big.min+'" max="'+K.big.max+'"></label></div></fieldset>'
