      if(q){var wa=$('#s-pm-wa',ft);if(wa)wa.href='https://wa.me/'+WA+'?text='+encodeURIComponent('Tere, sooviksin hinnapakkumist eritellimusel portselankivist valamule: '+basinSum(p,c)+'.')}
