  function assureHTML(door){var T=TR();return '<ul class="s-assure">'+(door&&T.garanziaPorte?'<li>'+IC.check+'<span><b>Garantii '+T.garanziaPorte+' aastat</b>, '+T.garanziaFerramenta+' aastat AGB hingedele ja lukule</span></li>':'')+'<li>'+IC.check+'<span><b>Vastame '+esc(T.risposta||'24 tundi')+'</b></span></li>'+(T.porteMese?'<li>'+IC.check+'<span><b>Üle '+T.porteMese+' ukse kuus</b> lahkub meie tehasest</span></li>':'')+'</ul>'}
  function payHTML(){var T=(TR().pagamento)||{anticipo:50,saldo:50,telefono:'+39 388 470 6887'},tel=T.telefono.replace(/\s/g,'');
    return '<div class="s-pay"><b class="s-pay-t"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="2.5" y="5.5" width="19" height="13" rx="2"/><path d="M2.5 10h19M6 15h4"/></svg>Maksmisviis</b><ol><li><i>'+T.anticipo+'%</i><span><b>Ettemaks</b> tellimuse kinnitamisel</span></li><li><i class="m">✓</i><span><b>Mõõtmine</b> pärast ettemaksu</span></li><li><i>'+T.saldo+'%</i><span><b>Jääk</b> kui kaup on valmis</span></li></ol><p>Küsimusi toote või maksmise kohta? <a href="https://wa.me/'+WA+'" target="_blank" rel="noopener">Kirjutage meile WhatsAppis</a> või helistage <a href="tel:'+tel+'">'+esc(T.telefono)+'</a>.</p></div>'}
  function codeNote(tot){var N=OF().newsletter||{},c=codeApplied();if(!c||!tot)return '';return '<span class="s-pm-code">Teie koodiga −'+N.perc+'%: <b>'+eur.format(Math.round(tot*(100-N.perc)/100))+'</b> · aegub '+leftTxt(codeLeft())+'</span>'}
  function cartCalc(){
    var O=OF(),tiers=(O.doorQty||[]).slice().sort(function(a,b){return a.min-b.min}),N=O.newsletter||{},code=codeApplied();
    var bv=bundleOK(),dq=cart.reduce(function(a,l){return a+(l.type==='door'&&!l.bundle?l.qty:0)},0),tier=null,next=null;
    tiers.forEach(function(t){if(dq>=t.min)tier=t;else if(!next&&dq>0)next={need:t.min-dq,perc:t.perc}});
    var sub=0,disc=0,rows=cart.map(function(l){
      var g=l.unit*l.qty,best=[0,''];
      [[l.bundle&&bv[l.bundle]?l.bdisc||0:0,l.bname||'Komplekt'],[l.type==='door'&&!l.bundle&&tier?tier.perc:0,tier?tier.label:''],[code?N.perc:0,'kood '+code]].forEach(function(c){if(c[0]>best[0])best=c});
      var a=Math.round(g*best[0]/100);sub+=g;disc+=a;return{gross:g,perc:best[0],why:best[1],amount:a};
    });
    return{sub:sub,disc:disc,tot:sub-disc,rows:rows,next:next};
  }
  function orderText(){
    var K=cartCalc(),s='Tellimus Pandoora Shopist:\n\n';
    cart.forEach(function(l,i){var r=K.rows[i];s+='• '+l.qty+' × '+l.name+' — '+l.sum+' — '+eur.format(r.gross-r.amount)+(r.perc?' (−'+r.perc+'% '+r.why+')':'')+(l.iva==='escl'?' (km-ta)':'')+'\n'});
    var code=codeApplied();
    return s+(K.disc?'\nAllahindlused: −'+eur.format(K.disc):'')+'\nOrienteeriv kogusumma: '+eur.format(K.tot)+(code?'\nSooduskood: '+code:'')+'\n\nNimi:\nTarnekoht:\nTelefon:';
  }
